def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    mask = objective[:, :, None] < objective[:, None, :]
    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)
    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'ref_all_pairs'})

def generated_loss(batch, model_output, extra):
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']
    weight = batch.get('weight', ops.ones_like(lpw))
    adv_gap = batch['advantage_gap']
    adv_sq = ops.mul(adv_gap, adv_gap)
    score_diff = ops.sub(lpw, lpl)
    loss_raw = ops.mul(ops.softplus(ops.neg(score_diff)), adv_sq)
    weighted_loss = ops.mul(loss_raw, weight)
    # Assuming batch has a dimension for grouping pairs per instance; fallback to global sum if not
    if 'instance_mask' in batch:
        # sum loss for each instance (assuming instance_mask is batch shape)
        instance_sums = ops.sum(weighted_loss, axis=1)
        return ops.mean(instance_sums)
    else:
        return ops.mean(ops.sum(weighted_loss, axis=0))
